p="$1"; case "$p" in "~/"*) p="$HOME/${p#??}";; esac; case "$p" in /*) ;; *) p="$PWD/$p";; esac; [ -e "$p" ] || { echo "No such file: $p"; exit 1; }; if [ "$(uname)" = Darwin ]; then open -R "$p"; exit $?; fi; [ -n "$DISPLAY$WAYLAND_DISPLAY" ] || { echo "No desktop on this machine to open it on"; exit 1; }; u=$(printf %s "$p" | sed 's/%/%25/g; s/ /%20/g; s/#/%23/g; s/?/%3F/g'); dbus-send --session --print-reply --reply-timeout=3000 --dest=org.freedesktop.FileManager1 --type=method_call /org/freedesktop/FileManager1 org.freedesktop.FileManager1.ShowItems array:string:"file://$u" string:"" >/dev/null 2>&1 || (${BACKPLANE_OPEN:-xdg-open} "$(dirname "$p")" >/dev/null 2>&1 &)